import pytest

from jinja2 import Environment
from jinja2.exceptions import SecurityError
from jinja2.sandbox import SandboxedEnvironment
from jinja2.sandbox import unsafe


class WithGetattr:
    def __getattr__(self, name):
        if name == "dynamic":
            return "dynamic-value"
        raise AttributeError(name)


class WithProperty:
    @property
    def value(self):
        return "prop-value"


class Unsafe:
    def bar(self):
        return "bar"

    @unsafe
    def secret(self):
        return "secret"


@pytest.fixture
def env():
    return Environment()


def test_attr_does_not_fall_back_to_item(env):
    # Unlike `foo[name]`, `foo|attr(name)` must never read dict items even
    # though Environment.getattr() would normally fall back to __getitem__.
    tmpl = env.from_string('{{ data|attr("spam") }}')
    assert tmpl.render(data={"spam": "eggs"}) == ""


def test_attr_finds_real_attribute_that_shadows_item_key(env):
    tmpl = env.from_string('{{ data|attr("items")()|list }}')
    assert tmpl.render(data={"items": 42}) == "[('items', 42)]"


def test_attr_missing_attribute_is_undefined(env):
    class Plain:
        pass

    tmpl = env.from_string('{{ obj|attr("missing") }}')
    assert tmpl.render(obj=Plain()) == ""


def test_attr_dynamic_getattr_found(env):
    tmpl = env.from_string('{{ obj|attr("dynamic") }}')
    assert tmpl.render(obj=WithGetattr()) == "dynamic-value"


def test_attr_dynamic_getattr_not_found(env):
    tmpl = env.from_string('{{ obj|attr("other") }}')
    assert tmpl.render(obj=WithGetattr()) == ""


def test_attr_property_value(env):
    tmpl = env.from_string('{{ obj|attr("value") }}')
    assert tmpl.render(obj=WithProperty()) == "prop-value"


def test_attr_filter_sandboxed_safe_attribute():
    sandbox_env = SandboxedEnvironment()
    tmpl = sandbox_env.from_string('{{ obj|attr("bar")() }}')
    assert tmpl.render(obj=Unsafe()) == "bar"


def test_attr_filter_sandboxed_unsafe_attribute():
    sandbox_env = SandboxedEnvironment()
    tmpl = sandbox_env.from_string('{{ obj|attr("secret")() }}')

    with pytest.raises(SecurityError):
        tmpl.render(obj=Unsafe())


def test_attr_filter_sandboxed_no_item_fallback():
    sandbox_env = SandboxedEnvironment()
    tmpl = sandbox_env.from_string('{{ data|attr("spam") }}')
    assert tmpl.render(data={"spam": "eggs"}) == ""

