import pytest

from jinja2 import Undefined
from jinja2.sandbox import SandboxedEnvironment


class Named:
    def __init__(self, name):
        self.name = name


class DynamicAttrs:
    """Only exposes attributes through __getattr__, not via the
    instance/class dict, so plain getattr_static can't see them."""

    def __getattr__(self, name):
        if name == "foo":
            return "bar"
        raise AttributeError(name)


class ItemFallback:
    """Supports item lookup but has no matching attribute."""

    def __getitem__(self, key):
        if key == "name":
            return "item-value"
        raise KeyError(key)


class TestAttrFilter:
    def test_existing_attribute(self, env):
        tmpl = env.from_string('{{ obj|attr("name") }}')
        assert tmpl.render(obj=Named("john")) == "john"

    def test_missing_attribute_is_undefined(self, env):
        tmpl = env.from_string('{{ obj|attr("missing") is undefined }}')
        assert tmpl.render(obj=Named("john")) == "True"

    def test_does_not_fall_back_to_item_lookup(self, env):
        # Unlike plain attribute/item resolution (``foo.bar``), the attr
        # filter must never resolve via __getitem__.
        obj = ItemFallback()
        assert obj["name"] == "item-value"

        tmpl = env.from_string('{{ obj|attr("name") is undefined }}')
        assert tmpl.render(obj=obj) == "True"

    def test_dynamic_attribute_via_getattr(self, env):
        # Attributes only reachable through __getattr__ (not discoverable by
        # inspect.getattr_static) must still be returned.
        tmpl = env.from_string('{{ obj|attr("foo") }}')
        assert tmpl.render(obj=DynamicAttrs()) == "bar"

    def test_dynamic_attribute_missing_is_undefined(self, env):
        tmpl = env.from_string('{{ obj|attr("missing") is undefined }}')
        assert tmpl.render(obj=DynamicAttrs()) == "True"

    def test_default_filter_chain(self, env):
        tmpl = env.from_string('{{ obj|attr("missing")|default("fallback", true) }}')
        assert tmpl.render(obj=Named("john")) == "fallback"

    def test_direct_call_returns_undefined_instance(self, env):
        from jinja2.filters import do_attr

        result = do_attr(env, Named("john"), "missing")
        assert isinstance(result, Undefined)

    def test_direct_call_returns_value(self, env):
        from jinja2.filters import do_attr

        assert do_attr(env, Named("john"), "name") == "john"

    def test_sandboxed_blocks_unsafe_attribute(self):
        senv = SandboxedEnvironment()
        tmpl = senv.from_string('{{ obj|attr("__class__") is undefined }}')
        assert tmpl.render(obj=object()) == "True"

    def test_sandboxed_allows_safe_attribute(self):
        senv = SandboxedEnvironment()
        tmpl = senv.from_string('{{ obj|attr("name") }}')
        assert tmpl.render(obj=Named("jane")) == "jane"

    def test_nonstring_name_raises_type_error(self, env):
        from jinja2.filters import do_attr

        with pytest.raises(TypeError):
            do_attr(env, Named("john"), 123)
